#include <stdio.h>
#include <math.h>

typedef struct { float x, y, z; } V;

static V mk(float a, float b, float c) { V r; r.x = a; r.y = b; r.z = c; return r; }
static V ad(V a, V b) { return mk(a.x + b.x, a.y + b.y, a.z + b.z); }
static V sb(V a, V b) { return mk(a.x - b.x, a.y - b.y, a.z - b.z); }
static V ml(V a, float t) { return mk(a.x * t, a.y * t, a.z * t); }
static float dt(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static V nz(V a) { float l = (float)sqrt((double)dt(a, a)); return mk(a.x / l, a.y / l, a.z / l); }

#define PLANE_Y (-1.5f)
#define SR 1.0f
#define AMB 0.2f

static const V SC = { 0.0f, -0.5f, -5.0f };

static int hit_sphere(V o, V d, float *tout, V *nout)
{
    V oc = sb(o, SC);
    float a = dt(d, d);
    float b = 2.0f * dt(oc, d);
    float c = dt(oc, oc) - SR * SR;
    float disc = b * b - 4.0f * a * c;
    float s, t;
    if (disc < 0.0f) return 0;
    s = (float)sqrt((double)disc);
    t = (float)(((double)(-b) - (double)s) / (double)(2.0f * a));
    if (t < 0.001f) {
        t = (float)(((double)(-b) + (double)s) / (double)(2.0f * a));
        if (t < 0.001f) return 0;
    }
    *tout = t;
    if (nout) *nout = nz(sb(ad(o, ml(d, t)), SC));
    return 1;
}

static int hit_plane(V o, V d, float *tout, V *pout)
{
    float t;
    if (fabsf(d.y) < 1e-4f) return 0;
    t = (PLANE_Y - o.y) / d.y;
    if (t < 0.001f) return 0;
    *tout = t;
    *pout = ad(o, ml(d, t));
    return 1;
}

static V trace(V o, V d, V light)
{
    float ts = 0.0f, tp = 0.0f, dummy;
    V ns, pp, p, n, base;
    int hs, hp, is_sphere;
    float diff;

    hs = hit_sphere(o, d, &ts, &ns);
    hp = hit_plane(o, d, &tp, &pp);

    if (hs && (!hp || tp > ts)) {
        is_sphere = 1;
        p = ad(o, ml(d, ts));
        n = ns;
    } else if (hp) {
        is_sphere = 0;
        p = pp;
        n = mk(0.0f, 1.0f, 0.0f);
    } else {
        float t = 0.5f * (d.y + 1.0f);
        return ad(ml(mk(0.5f, 0.7f, 1.0f), t), ml(mk(1.0f, 1.0f, 1.0f), 1.0f - t));
    }

    diff = dt(n, light);
    if (diff < 0.0f) diff = 0.0f;
    if (hit_sphere(ad(p, ml(n, 0.001f)), nz(light), &dummy, (V *)0)) diff = 0.0f;
    diff = (1.0f - AMB) * diff + AMB;

    if (is_sphere) {
        base = mk(1.0f, AMB, AMB);
    } else {
        int chk = (((int)(floor((double)p.x) + floor((double)p.z))) & 1) == 0;
        base = chk ? mk(0.9f, 0.9f, 0.9f) : mk(0.4f, 0.4f, 0.4f);
    }
    return ml(base, diff);
}

int main(void)
{
    const int W = 2400, H = 1800;
    float vh = 2.0f;
    float vw = ((float)W / (float)H) * vh;
    float fl = 1.0f;
    V origin = mk(0.0f, 0.0f, 0.0f);
    V horiz = mk(vw, 0.0f, 0.0f);
    V vert = mk(0.0f, vh, 0.0f);
    V depth = mk(0.0f, 0.0f, fl);
    V llc = sb(sb(sb(origin, ml(horiz, 0.5f)), ml(vert, 0.5f)), depth);
    V light = nz(mk(1.0f, 1.0f, -1.0f));
    FILE *f;
    char *buf, *q;
    int i, j;

    f = fopen("reconstructed.ppm", "w");
    if (!f) return 1;
    fprintf(f, "P3\n%d %d\n255\n", W, H);

    buf = (char *)malloc((size_t)W * 12 + 16);
    for (j = 0; j < H; j++) {
        float v = (float)j / (float)(H - 1);
        q = buf;
        for (i = 0; i < W; i++) {
            float u = (float)i / (float)(W - 1);
            V dir = ad(llc, ad(ml(horiz, u), sb(ml(vert, 1.0f - v), origin)));
            V col = trace(origin, nz(dir), light);
            float cc[3];
            int k;
            cc[0] = col.x; cc[1] = col.y; cc[2] = col.z;
            for (k = 0; k < 3; k++) {
                int val;
                float c = cc[k];
                if (c < 0.0f) c = 0.0f;
                if (c > 1.0f) c = 1.0f;
                val = (int)(255.99f * c);
                if (val >= 100) *q++ = (char)('0' + val / 100);
                if (val >= 10) *q++ = (char)('0' + (val / 10) % 10);
                *q++ = (char)('0' + val % 10);
                *q++ = (k == 2) ? '\n' : ' ';
            }
        }
        fwrite(buf, 1, (size_t)(q - buf), f);
    }
    free(buf);
    fclose(f);
    return 0;
}
